import glom
from glom import spec, auto, fill, iter_, let, ROOT

class Invoke:
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self.args = args
        self.kwargs = kwargs

    def __repr__(self):
        return f"Invoke({self.func}, {self.args}, {self.kwargs})"

    @property
    def constants(self):
        return self.func.__code__.co_consts

    def __call__(self):
        return self.func(*self.args, **self.kwargs)
